import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { createContext } from "svelte";
export type WindowPlatform = "windows" | "macos" | "linux";
export interface WindowState {
  maximized: boolean;
  focused: boolean;
}
export interface WindowHost {
  state: WindowState;
  capabilities: {
    minimize: boolean;
    maximize: boolean;
    close: boolean;
    move: boolean;
  };
  minimize(): void | Promise<void>;
  toggleMaximize(): void | Promise<void>;
  close(): void | Promise<void>;
  startDragging?(): void | Promise<void>;
}
export interface WindowContext {
  readonly host: WindowHost;
  readonly onError: (error: unknown) => void;
}
const [getContext, setContext] = createContext<WindowContext>();
export const setWindowHostContext = setContext;
export function useWindowHost() {
  try {
    return getContext();
  } catch {
    throw new Error("Wrap window components in WindowHostProvider.");
  }
}
export function useWindowAction() {
  const context = useWindowHost();
  return (action: () => void | Promise<void>) => {
    try {
      Promise.resolve(action()).catch((error) => context.onError(error));
    } catch (error) {
      context.onError(error);
    }
  };
}

import type { WindowHost, WindowState } from "./window-host";
/** Structural subset of your application-generated Runic Views client. */
export interface RunicWindowCommands {
  minimize(): Promise<unknown>;
  toggleMaximized(): Promise<unknown>;
  requestClose(): Promise<unknown>;
}
export interface RunicWindowSnapshot extends WindowState {
  canMinimize: boolean;
  canToggleMaximized: boolean;
  canRequestClose: boolean;
  canMove: boolean;
}
/** Derive a new host from useView's current snapshot. useView owns its client. */
export function createRunicWindowHost(
  client: RunicWindowCommands,
  state: RunicWindowSnapshot,
): WindowHost {
  return {
    state,
    capabilities: {
      minimize: state.canMinimize,
      maximize: state.canToggleMaximized,
      close: state.canRequestClose,
      move: state.canMove,
    },
    minimize: async () => {
      await client.minimize();
    },
    toggleMaximize: async () => {
      await client.toggleMaximized();
    },
    close: async () => {
      await client.requestClose();
    },
    // Runic Desktop's authenticated bootstrap owns --webui-app-region dragging.
  };
}
